fault_script:
#!/bin/bash
set -euo pipefail
exec >>/home/phat/ml-experiments/326395a2bcc0/fault.log 2>&1
echo FAULT_BEFORE $(date -u +%s)
nft add table inet mlv2_326395a2bcc0
nft 'add chain inet mlv2_326395a2bcc0 output { type filter hook output priority 0; policy accept; }'
nft add rule inet mlv2_326395a2bcc0 output udp dport 53 counter drop
nft add rule inet mlv2_326395a2bcc0 output tcp dport 53 counter drop
nft list table inet mlv2_326395a2bcc0
echo FAULT_VERIFIED $(date -u +%s)

rollback_script:
#!/bin/bash
set -euo pipefail
exec >>/home/phat/ml-experiments/326395a2bcc0/rollback.log 2>&1
echo ROLLBACK_BEFORE $(date -u +%s)
tables="$(nft list tables)"
if printf '%s\n' "$tables" | grep -Fxq 'table inet mlv2_326395a2bcc0'; then
  nft delete table inet mlv2_326395a2bcc0
fi
echo ROLLBACK_AFTER $(date -u +%s)
